//! Melting and sublimation line comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_solid_lines.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::solid;

fn parse(case: &str) -> (&str, &str, f64) {
    let parts: Vec<_> = case.split('|').collect();
    (parts[0], parts[1], parts[2].parse().unwrap())
}

#[test]
fn solid_lines_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/solid_lines.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let (kind, component, limit) = parse(fields[0]);
        let expected_t: Vec<f64> = fields[1].split(',').map(|v| v.parse().unwrap()).collect();
        let expected_p: Vec<f64> = fields[2].split(',').map(|v| v.parse().unwrap()).collect();
        let line = if kind == "MELT" {
            solid::melting_line(component, limit, expected_t.len()).unwrap()
        } else {
            solid::sublimation_line(component, limit, expected_t.len()).unwrap()
        };
        assert_eq!(line.temperature.len(), expected_t.len(), "{}", fields[0]);
        for (position, (source, native)) in
            expected_t.iter().zip(line.temperature.iter()).enumerate()
        {
            let tolerance = 1e-4 + 1e-10 * source.abs();
            assert!(
                (source - native).abs() <= tolerance,
                "{} temperature {position}: source {source} native {native}",
                fields[0]
            );
        }
        for (position, (source, native)) in expected_p.iter().zip(line.pressure.iter()).enumerate()
        {
            if source.is_nan() {
                assert!(native.is_nan(), "{} pressure {position}", fields[0]);
                continue;
            }
            let tolerance = 1e-4 + 1e-10 * source.abs();
            assert!(
                (source - native).abs() <= tolerance,
                "{} pressure {position}: source {source} native {native}",
                fields[0]
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 152);
}

#[test]
fn solid_source_status_is_reproduced() {
    let mut statuses = [0usize; 4];
    for row in include_str!("fixtures/solid_lines_status.csv")
        .lines()
        .skip(1)
    {
        let (case, status) = row.split_once(';').unwrap();
        let status: usize = status.parse().unwrap();
        let (kind, component, limit) = parse(case);
        let outcome = if kind == "MELT" {
            solid::melting_line(component, limit, 7)
        } else {
            solid::sublimation_line(component, limit, 7)
        };
        // The hydrogen sulfide record has no usable fourth correlation
        // character, so the original stops there.
        assert_eq!(outcome.is_err(), status == 1, "{case}");
        statuses[status] += 1;
    }
    assert_eq!(statuses[0], 152);
    assert_eq!(statuses[1], 4);
    assert_eq!(statuses[2], 0);
    assert_eq!(statuses[3], 0);
}

#[test]
fn solid_correlation_database_is_complete() {
    // Every melting and sublimation record must be resolvable.
    for component in [
        "NH3", "AR", "CO2", "CO", "CYCLOHEX", "C2", "HE", "H2", "IC4", "IC5", "KR", "C1", "MEOH",
        "NE", "N2", "O2", "P-H2", "C3", "PRLN", "F6S", "XE", "NC4", "NC5",
    ] {
        assert!(thermopack_rs::lookup_melting_correlation(component).is_some());
    }
    for component in [
        "NH3", "AR", "CO2", "CO", "C2", "H2", "H2S", "KR", "C1", "NE", "N2", "N2O", "O2", "P-H2",
        "F6S", "XE",
    ] {
        assert!(thermopack_rs::lookup_sublimation_correlation(component).is_some());
    }
    assert!(thermopack_rs::lookup_melting_correlation("NOT_A_COMPONENT").is_none());
    // The melting line of carbon dioxide starts at its triple point.
    let line = solid::melting_line("CO2", 300.0, 5).unwrap();
    assert!(line.pressure[0] > 0.0);
    assert!(line.temperature.windows(2).all(|w| w[0] <= w[1]));
    // A component without a correlation is an error.
    assert!(solid::melting_line("NOT_A_COMPONENT", 300.0, 5).is_err());
    assert!(solid::sublimation_line("NOT_A_COMPONENT", 50.0, 5).is_err());
    // The hydrogen sulfide sublimation record has no usable fourth
    // correlation character and stops like the original.
    assert!(solid::sublimation_line("H2S", 100.0, 5).is_err());
}
